import sys
from collections import deque

MOD = 10**9 + 7

def bfs_shortest_paths(graph, start, n):
    dist = [float('inf')] * (n + 1)
    dist[start] = 0
    queue = deque([start])
    while queue:
        u = queue.popleft()
        for v in graph[u]:
            if dist[v] == float('inf'):
                dist[v] = dist[u] + 1
                queue.append(v)
    return dist

def count_paths(graph, dist, start, target, max_length):
    dp = [[0] * (max_length + 1) for _ in range(n + 1)]
    dp[start][0] = 1
    for length in range(max_length + 1):
        for u in range(1, n + 1):
            for v in graph[u]:
                if dist[u] + 1 == dist[v] and length > 0:
                    dp[v][length] = (dp[v][length] + dp[u][length - 1]) % MOD
                elif dist[u] == dist[v] + 1:
                    dp[u][length] = (dp[u][length] + dp[v][length]) % MOD
    return sum(dp[target][:max_length + 1]) % MOD

def main():
    import sys
    input = sys.stdin.read().splitlines()
    index = 0
    t = int(input[index])
    results = []
    while index < len(input):
        index += 1
        n, m = map(int, input[index].split())
        s, t = map(int, input[index + 1].split())
        graph = [[] for _ in range(n + 1)]
        for _ in range(m):
            u, v = map(int, input[index + 2].split())
            graph[u].append(v)
            graph[v].append(u)
        index += m + 2
        dist = bfs_shortest_paths(graph, s, n)
        if dist[t] == float('inf'):
            results.append(0)
        else:
            results.append(count_paths(graph, dist, s, t, dist[t] + 1))
    for result in results:
        print(result)

if __name__ == "__main__":
    main()
